mapper.select:
SELECT EXISTS(SELECT 1 FROM nw_execution_artifact_public_inspections
  WHERE tenant_id=CAST(#{tenant} AS bigint) AND artifact_id=#{artifact} AND path=#{path}
    AND sha256=#{sha256} AND size=#{size} AND scope_digest=#{scopeDigest} AND policy_version=#{policyVersion})

SELECT s.end_user_id::text FROM nw_chat_sessions s
  JOIN nw_end_users u ON u.tenant_id=s.tenant_id AND u.id=s.end_user_id AND u.status='active'
WHERE s.tenant_id=CAST(#{tenant} AS bigint) AND s.session_id=#{session}
